_MISSING_STATUS_CODE = {'table': '1.1', 'no_binary': '1.3', 'no_state': '1.4'}


def as_missing_list(value):
    """
    The missing-binary entries as a list, whatever the caller has.

    v1.2.5: batch_additivity stores `'; '.join(missing)`, so the classifier
    was handed a STRING and iterated it character by character - every one of
    the 20 tier-1 perovskites came out 1.4 with a reason built from single
    letters. Every test I wrote passed a list, because I built the frames
    myself or read them back with literal_eval. One place converts now, and
    it takes a list, a joined string, or the repr of a list.
    """
    if value is None:
        return []
    if isinstance(value, (list, tuple)):
        return [v for v in value if v]
    if not isinstance(value, str):
        return []                       # NaN from an empty CSV cell
    text = value.strip()
    if not text or text in ('[]', 'nan'):
        return []
    if text.startswith('[') and text.endswith(']'):
        import ast as _ast
        try:
            lit = _ast.literal_eval(text)
            if isinstance(lit, (list, tuple)):
                return [v for v in lit if v]
        except (ValueError, SyntaxError):
            pass
    return [p.strip() for p in text.split(';') if p.strip()]


def _rounded_from_missing(entry):
    """Whether this request came from a rounded site mean, per the string."""
    return isinstance(entry, str) and 'rounded)' in entry


def _binary_from_missing(entry):
    """The binary formula out of one `missing_binaries` string, or None.

    The strings are written by decompose_ternary as 'Ru2O3 (not in table)'
    and 'Fe+4.0 (no pattern)'. Only the first form names a binary.
    """
    if not isinstance(entry, str):
        return None
    head = entry.split(' (')[0].strip()
    return head if '(not in table)' in entry else None


def classify_missing_binaries(missing, detail=None):
    # v1.2.5: `detail` is kept in the signature for anything that still
    # passes it, and ignored: the rounding fact is in the string now.
    """
    Which code a decomposition that lacked a binary belongs in, and why.

    v1.2.3: 1.1 held four different findings. Returns (code, reason).

    The rounding evidence wins where it exists: a request built on a
    non-integral site mean is 1.4 whatever the registry says, because the
    charge was never an oxidation state. Otherwise the registry decides, and
    an unregistered binary stays 1.1 and says so.

    Where a structure is missing more than one binary the strongest finding
    wins, in the order 1.4, 1.3, 1.1: a structure whose decomposition rests
    on a charge that does not exist is not waiting on our table.
    """
    reasons, codes = [], []
    for entry in as_missing_list(missing):
        formula = _binary_from_missing(entry)

        if _rounded_from_missing(entry):
            codes.append('1.4')
            reasons.append(f'{entry}: asked for from a rounded site mean, '
                           f'which was not an oxidation state')
            continue

        if formula is None:
            codes.append('1.4')
            reasons.append(f'{entry}: no binary pattern for that charge')
            continue

        status = MISSING_BINARY_STATUS.get(formula)
        if status is None:
            codes.append('1.1')
            reasons.append(f'{formula}: UNCLASSIFIED, not in '
                           f'MISSING_BINARY_STATUS')
            continue
        codes.append(_MISSING_STATUS_CODE[status[0]])
        reasons.append(f'{formula}: {status[1]}')

    if not codes:
        return '1.1', 'decomposition failed with no binary named'
    for code in ('1.4', '1.3', '1.1'):
        if code in codes:
            return code, '; '.join(reasons)
    return '1.1', '; '.join(reasons)


# ── The population a residual statistic is drawn from ──────────────────────
def additivity_population(df):
    """
    The structures whose residual IS a residual: decomposition complete and
    delta computed.

    v1.2.1: Figure 1 selected on delta.notna() while the classifier counted
    tier 0, so the figure said 662 within 1% and the classification said 661
    additive, on the same run and in the same paper. One definition, used by
    both.
    """
    return df[df['success'].astype(bool) & df['delta_pct'].notna()]


def n_classified_additive(df):
    """How many structures the classifier called additive. One number."""
    return int((additivity_population(df)['classification'] == 'Additive').sum())


# Convenience lookups
def _tier_for_code(code):
    """Return the tier for a classification outcome.

    v1.2.7: 'Additive' is an outcome without a registry code, and it is
    tier 0. Callers that map over CODE_ORDER meet it first, so answering
    here is better than every caller special-casing it.
    """
    if code == 'Additive':
        return 0
    return CLASSIFICATION_REGISTRY[code][0]

def _label_for_code(code):
    """Return the human-readable label for a classification code."""
    return CLASSIFICATION_REGISTRY[code][1]

"""
Code 2.5 detector: Wyckoff 4a/4b site mis-assignment in Pnma perovskites.

Detects ICSD entries where the B-site cation is deposited at Wyckoff 4a
instead of the correct 4b in GdFeO3-type perovskites (Pnma, 20 sites).

v1.1: the counts that used to sit here have been removed. They disagreed
with the registry and with the manuscript, and the notebook reports the
population it finds.

Usage in the Hopper classification cell:
    
    wyckoff_error = detect_wyckoff_site_error(
        row['source_cif'], results_df, summary_df
    )
    if wyckoff_error:
        code = '2.5'
        label = 'Wyckoff site mis-assignment (B at 4a instead of 4b)'
"""


def detect_structural_coordinate_error(cif_name, results_df, summary_df,
                                        cv_threshold=0.05,
                                        results_index=None,
                                        summary_index=None):
    """
    Detect structural coordinate errors in Pnma perovskites using the
    coefficient of variation (CV) of per-site oxygen MAPLE values.
 
    In a correctly refined GdFeO3-type perovskite (Pnma, Z=4, 20 sites),
    the 12 oxygen sites occupy two crystallographically distinct positions
    (Wyckoff 4c and 8d) but experience similar electrostatic environments,
    giving per-site MAPLE values within ~5% of each other (CV < 0.045).
 
    Structural coordinate errors distort the local coordination geometry
    and produce anomalously different MAPLE values between O1 and O2
    sublattices, pushing CV above 0.05.
 
    Parameters
    ----------
    cif_name : str
        Source CIF filename (must match a row in summary_df).
    results_df : pd.DataFrame
        Per-site MAPLE results with columns: source_cif, element,
        maple_kcal_mol.
    summary_df : pd.DataFrame
        Per-structure summary with columns: source_cif, Z, space_group.
    cv_threshold : float
        CV threshold above which the structure is flagged.
        Default 0.05 (validated gap: 0.045-0.050).
 
    Returns
    -------
    bool or None
        True  — structural coordinate error detected (classify as 2.5).
        False — structure is clean.
        None  — structure is not a testable Pnma perovskite.
    """
    srow = rows_for(cif_name, summary_df, summary_index)
    if len(srow) == 0:
        return None
    srow = srow.iloc[0]
 
    # v1.1: THE TEST NO LONGER GATES ON Z.
    #
    # This asked for Z == 4, so every perovskite whose Z had been lost to
    # composition reduction - 101 of the 938, all non-stoichiometric - was
    # returned as untestable and never screened for coordinate errors at all.
    # The claim of zero false positives across 938 was really across 831.
    #
    # What the test actually needs is a 20-site Pnma cell with 12 oxygens,
    # which is checked below and does not require Z. With MaplePy v1.1
    # deriving Z from the site counts the two conditions coincide anyway, and
    # a test should not depend on a quantity it does not use.
    if srow['space_group'] != 'Pnma':
        return None
 
    entry = rows_for(cif_name, results_df, results_index)
    if len(entry) != 20:
        return None
 
    oxygens = entry[entry['element'] == 'O']
    if len(oxygens) != 12:
        return None
 
    # Coefficient of variation of per-site oxygen MAPLE
    o_maples = oxygens['maple_kcal_mol'].values.astype(float)
    o_mean = np.mean(o_maples)
 
    if o_mean <= 0:
        return None
 
    cv = float(np.std(o_maples) / o_mean)
 
    # Explicit bool() to avoid numpy.bool_ identity issues
    return bool(cv > cv_threshold)

def _summary_field(cif_name, summary_df, column, summary_index=None):
    """
    One field of MaplePy's summary for one structure, or None.

    v1.2.2: the three tests below all need the same lookup, and all three
    must answer None rather than False when MaplePy did not write the
    column - a test that cannot run is not a test that passed.
    """
    if column not in summary_df.columns:
        return None
    srow = rows_for(cif_name, summary_df, summary_index)
    if len(srow) == 0:
        return None
    value = srow[column].iloc[0]
    return value if isinstance(value, str) else None


def detect_split_site(cif_name, summary_df, summary_index=None):
    """
    Whether MaplePy flagged this structure as a split-site disorder model.

    v1.2.2: reads `geometry_flag`, written by MaplePy v1.3.3. It used to read
    the prefix of `geometry_status`, which is a sentence written for a human:
    Hopper's classification should not depend on MaplePy's wording.

    Hopper does not recompute the geometry. MaplePy holds the structures and
    the tolerances, and two implementations of one test is how they come to
    disagree.
    """
    flag = _summary_field(cif_name, summary_df, 'geometry_flag',
                           summary_index)
    return None if flag is None else flag == 'split_site'


def detect_short_contact(cif_name, summary_df, summary_index=None):
    """
    Whether the shortest contact is below MaplePy's SHORT_CONTACT_ANG.

    v1.2.2: the second detector for code 2.5. The CV test needs a 20-site
    Pnma cell with 12 oxygens and cannot see a short contact anywhere else;
    NdFeO3 at 1.507 A was classified Additive at delta 0.312% because of it.
    """
    flag = _summary_field(cif_name, summary_df, 'geometry_flag',
                           summary_index)
    return None if flag is None else flag == 'short_contact'


def detect_anion_vacancy(cif_name, summary_df, summary_index=None):
    """
    Whether the fractional occupancy is on the anion sublattice alone.

    v1.2.2: code 2.6, reserved since the first version and assignable now
    that MaplePy v1.3.3 writes `partial_sublattice`. Anion-only, not 'both':
    a structure with cation disorder as well is a mean-field result for more
    than one reason and belongs in 2.3.
    """
    where = _summary_field(cif_name, summary_df, 'partial_sublattice',
                           summary_index)
    return None if where is None else where == 'anion'


def classify_additivity(df_add, results_df, summary_df,
                        threshold_additive=ADDITIVE_THRESHOLD_PCT):
    """
    Assign a tiered numeric classification to each structure based on
    its additivity residual and metadata.

    Parameters
    ----------
    df_add : DataFrame
        Output from batch_additivity(), one row per structure.
    results_df, summary_df : DataFrame
        MaplePy's per-site and per-structure output. v1.1: these were read
        as free variables from the notebook namespace, so re-running the
        cells out of order classified against a stale frame silently.
    threshold_additive : float
        Residual threshold (%) below which a structure is classified
        as additive.  Default 1.0 (Hoppe criterion).

    Returns
    -------
    DataFrame with added columns:
        classification       str   'Additive' or code ('1.1', '2.1', etc.)
        classification_tier  int   0 for additive, 1/2/3 for failures
        classification_label str   human-readable label

    Notes
    -----
    Priority order follows ascending code number.  A structure that
    could trigger both 2.1 and 2.3 receives 2.1 (the lower code).
    Additive status is checked first: delta < threshold -> additive, stop.
    """
    df = df_add.copy()
    # v1.2.4: two indexes, built once, for every lookup below.
    _ridx = index_by_cif(results_df) if len(results_df) else None
    _sidx = index_by_cif(summary_df) if len(summary_df) else None
    df['classification']       = ''
    df['classification_tier']  = 0
    df['classification_label'] = ''
    df['hopper_version']       = HOPPER_VERSION
    df['missing_binary_reason'] = ''

    # v1.2.1: say when a test cannot run. Against CSVs written before MaplePy
    # v1.3.2 there is no geometry column, and a split-site structure would
    # then be classified on whatever else it trips - which is how all four of
    # them came to be called oxygen non-stoichiometry.
    for _col, _tests in (('geometry_flag', 'the split-site test (2.7) and '
                          'the short-contact half of 2.5'),
                         ('partial_sublattice', 'the anion-vacancy test (2.6)')):
        if _col not in summary_df.columns:
            print(f"  NOTE: no {_col} column in the summary. These CSVs were "
                  f"written by MaplePy before v1.3.3, so {_tests} did not "
                  f"run.")

    for idx, row in df.iterrows():

        # ── Codes 1.1, 1.3, 1.4: the decomposition lacked a binary ──
        # v1.2.3: three findings, not one. Which of them is decided by
        # classify_missing_binaries, from the rounding evidence where
        # there is any and from the registry where there is not.
        if not row['success'] and as_missing_list(
                row['missing_binaries']):
            _code, _why = classify_missing_binaries(row['missing_binaries'])
            df.at[idx, 'classification']       = _code
            df.at[idx, 'classification_tier']   = 1
            df.at[idx, 'classification_label']  = (
                f'{_label_for_code(_code)} ({_why})' if _code == '1.1'
                and 'UNCLASSIFIED' in _why else _label_for_code(_code))
            df.at[idx, 'missing_binary_reason'] = _why
            if 'UNCLASSIFIED' in _why:
                print(f"  NOTE: {row['source_cif']} asks for a binary that is "
                      f"not in MISSING_BINARY_STATUS - {_why}")
            continue

        # Catch-all for other decomposition failures (should not occur
        # with current data, but defensive)
        if not row['success']:
            df.at[idx, 'classification']       = '1.1'
            df.at[idx, 'classification_tier']   = 1
            df.at[idx, 'classification_label']  = 'Decomposition failed'
            continue

        # ── Guard: success=True but delta_pct unavailable ───────────
        # Can occur when maple_ternary == maple_binary_sum exactly,
        # producing delta_abs = 0.0 that becomes NaN through a
        # rounding or serialisation artefact.  Treat as additive.
        if row['delta_pct'] is None or (isinstance(row['delta_pct'], float)
                                         and row['delta_pct'] != row['delta_pct']):
            df.at[idx, 'classification']       = 'Additive'
            df.at[idx, 'classification_tier']   = 0
            df.at[idx, 'classification_label']  = 'Additive'
            continue

        # ── Code 2.7: split-site disorder model ────────────────────
        # Checked before Additive, like 2.5: a structure whose two
        # half-occupied sites are 0.03 A apart is not additive when its
        # residual lands under 1%, it is unmeasured. MaplePy v1.3.2
        # flags these; see its SPLIT_SITE_ANG for the tolerance.
        if detect_split_site(row['source_cif'], summary_df, _sidx):
            df.at[idx, 'classification']       = '2.7'
            df.at[idx, 'classification_tier']   = 2
            df.at[idx, 'classification_label']  = _label_for_code('2.7')
            continue

        # ── Code 2.5: structural coordinate error ──────────────────
        # Two detectors, either sufficient, and the label says which
        # found it. The CV test sees a B-site at 4a instead of 4b in a
        # 20-site Pnma cell; the distance test sees any contact below
        # SHORT_CONTACT_ANG anywhere.
        #
        # Both are checked before Additive, because DyCrO3 138222 passes
        # the 1% threshold by coincidence despite the Wyckoff error and
        # NdFeO3 passes it with two atoms 1.507 A apart.
        _cv = detect_structural_coordinate_error(
            row['source_cif'], results_df, summary_df,
            results_index=_ridx, summary_index=_sidx)
        _short = detect_short_contact(row['source_cif'], summary_df, _sidx)
        if _cv or _short:
            _how = ('O-site MAPLE CV and short contact' if _cv and _short
                    else 'short contact' if _short else 'O-site MAPLE CV')
            df.at[idx, 'classification']       = '2.5'
            df.at[idx, 'classification_tier']   = 2
            df.at[idx, 'classification_label']  = (
                f"{_label_for_code('2.5')} ({_how})")
            continue
        
        # ── Additive: delta < threshold ─────────────────────────────
        # Check additive status before entering the failure logic.
        # Structures within Hoppe range get no failure code.
        if (row['delta_pct'] is not None
                and row['delta_pct'] < threshold_additive):
            df.at[idx, 'classification']       = 'Additive'
            df.at[idx, 'classification_tier']   = 0
            df.at[idx, 'classification_label']  = 'Additive'
            continue

        # ── From here, delta >= threshold: assign failure codes ─────
        # Applied in ascending code order so the lowest applicable
        # code wins.

        # ── Code 2.1: oxidation state assignment error ──────────────
        # Very large residual (>10%) in an ordered structure with
        # balanced oxygen points to incorrect oxidation states in the
        # CIF, producing a wrong binary decomposition.
        if (row['delta_pct'] is not None and row['delta_pct'] > 10.0
                and not row['disordered'] and row['oxygen_balanced']):
            df.at[idx, 'classification']       = '2.1'
            df.at[idx, 'classification_tier']   = 2
            df.at[idx, 'classification_label']  = _label_for_code('2.1')
            continue

        # ── Code 2.2: defined, and unreachable from a MaplePy result ──
        # There was a branch here assigning 2.2 to every Z = 1 structure,
        # written when composition-derived Z made Z = 1 a reliable sign of
        # an artefact. MaplePy v1.1 derives Z from the site counts, the
        # population fell 107 -> 2, and the two survivors are cubic
        # perovskites whose Z really is 1. So no branch assigns 2.2 here:
        # a Z = 1 structure from MaplePy is classified on its residual like
        # any other. The CODE stays in the registry, because the artefact is
        # real for any tool that reads Z from the CIF or trusts a
        # compositional reduction, and it is reported as zero rather than
        # omitted.

        # ── Code 2.6: anion vacancy disorder ───────────────────────
        # Fractional occupancy on the anion sublattice alone: an
        # oxygen-deficient refinement. Tested before 2.3 because it is
        # the more specific description of the same structure, and
        # before 2.4 because it says WHY the oxygen does not balance.
        if detect_anion_vacancy(row['source_cif'], summary_df, _sidx):
            df.at[idx, 'classification']       = '2.6'
            df.at[idx, 'classification_tier']   = 2
            df.at[idx, 'classification_label']  = _label_for_code('2.6')
            continue

        # ── Code 2.3: disorder / mean-field approximation ───────────
        # Structure has mixed-occupancy sites processed via mean-field
        # charge averaging.  The residual may partly reflect the
        # averaging artefact rather than genuine structural chemistry.
        if row['disordered']:
            df.at[idx, 'classification']       = '2.3'
            df.at[idx, 'classification_tier']   = 2
            df.at[idx, 'classification_label']  = _label_for_code('2.3')
            continue

        # ── Code 2.4: oxygen non-stoichiometry ──────────────────────
        # Oxygen count from binary decomposition does not match the
        # ternary oxygen count.  Principal cause: Co3O4 used in place
        # of the non-existent Co2O3.
        if not row['oxygen_balanced']:
            df.at[idx, 'classification']       = '2.4'
            df.at[idx, 'classification_tier']   = 2
            df.at[idx, 'classification_label']  = _label_for_code('2.4')
            continue

        # ── Code 3.1: genuine violation ─────────────────────────────
        # delta >= threshold with correct oxidation states, correct Z,
        # balanced oxygen, no disorder.  The residual reflects genuine
        # structural chemistry (covalency, strain, etc.).
        if row['delta_pct'] is not None and row['delta_pct'] >= threshold_additive:
            df.at[idx, 'classification']       = '3.1'
            df.at[idx, 'classification_tier']   = 3
            df.at[idx, 'classification_label']  = _label_for_code('3.1')

    return df
